window.__GUEST__ = {"files": {"/app/공용/__init__.py": "", "/app/공용/보관함.py": "\"\"\"보관함 — 노트 파일(.md)을 읽고 쓰고, 목록·태그·링크·할 일을 기억해 둔다.\n\n노트는 그냥 마크다운 파일이다. 옵시디언으로 폴더째 열어도 그대로 보인다.\n이 프로그램만 아는 것(고정·보관·만든 날)은 보관함 안 `.musicits/상태.json` 에 따로 둔다.\n본문에 끼워 넣지 않아야 다른 앱으로 옮겨도 깨끗하다.\n\n    보관함/\n        일기/2026-10-16.md       데일리 노트\n        템플릿/일기.md            새 일기의 틀\n        첨부/                    붙여 넣은 사진\n        .trash/                  휴지통 (옵시디언과 같은 이름)\n        .musicits/상태.json       고정·보관·만든 날\n        .musicits/기록/           고치기 전 내용(버전 기록)\n\n맥이 나스에 파일을 올리면 한글 이름이 NFD 로 올 수 있다. 목록에서는 전부 NFC 로 맞추고,\n디스크의 실제 이름은 따로 기억한다(_실제).\n\"\"\"\n\nimport hashlib\nimport json\nimport os\nimport re\nimport shutil\nimport threading\nimport time\nimport unicodedata\nfrom datetime import datetime, timedelta\n\nNFC = lambda s: unicodedata.normalize(\"NFC\", s)\n\n앱폴더 = \".musicits\"\n휴지통 = \".trash\"\n노트확장자 = (\".md\", \".markdown\")\n그림확장자 = (\".png\", \".jpg\", \".jpeg\", \".gif\", \".webp\", \".svg\", \".heic\", \".avif\", \".bmp\")\n\n기본설정 = {\n    \"템플릿폴더\": \"템플릿\",\n    \"첨부폴더\": \"첨부\",\n    \"새노트폴더\": \"\",\n    \"일기제목형식\": \"%Y-%m-%d\",\n}\n\n# 일기 종류 — 달력 위 고르개가 이것이다. 설정에서 더하고 뺀다.\n#   캘린더: 이 일기에 짝지을 iCloud 캘린더 이름들(비우면 전부)\n기본_일기종류 = [\n    {\"이름\": \"회사\", \"폴더\": \"일기/회사\", \"템플릿\": \"템플릿/회사 일기.md\", \"캘린더\": []},\n    {\"이름\": \"블로그\", \"폴더\": \"일기/블로그\", \"템플릿\": \"템플릿/블로그 일기.md\", \"캘린더\": []},\n]\n\n# 템플릿 노트가 없을 때 쓰는 틀. '- ' 뒤 빈칸은 일부러 둔다(커서가 거기로 간다).\n기본_일기템플릿 = {\n    \"회사\": \"## 일정\\n{{일정}}\\n\\n## 오늘 한 일\\n- \\n\\n## 회의·메모\\n\\n\\n## 내일 할 일\\n- [ ] \\n\\n#일기/회사\\n\",\n    \"블로그\": \"## 일정\\n{{일정}}\\n\\n## 쓴 글·올린 글\\n- \\n\\n## 글감\\n- \\n\\n## 숫자 (방문자·이웃·조회)\\n\\n\\n## 내일 할 일\\n- [ ] \\n\\n#일기/블로그\\n\",\n}\n기본_일기템플릿_공통 = \"## 일정\\n{{일정}}\\n\\n## 오늘 한 일\\n- \\n\\n## 메모\\n\\n\\n## 내일 할 일\\n- [ ] \\n\\n#일기\\n\"\n\n\nclass 충돌(Exception):\n    \"\"\"다른 기기에서 먼저 고쳤다. 지금 내용과 판(ver)을 같이 싣는다.\"\"\"\n    def __init__(self, text, ver):\n        super().__init__(\"conflict\")\n        self.text, self.ver = text, ver\n\n\nclass 없음(Exception):\n    pass\n\n\n# ── 본문에서 뽑기 ──────────────────────────────────────────────────────\n\n_fence = re.compile(r\"^(```|~~~)[^\\n]*\\n.*?^\\1[ \\t]*$\", re.S | re.M)\n_inline_code = re.compile(r\"`[^`\\n]*`\")\n_front = re.compile(r\"\\A---[ \\t]*\\n(.*?)\\n(?:---|\\.\\.\\.)[ \\t]*(?:\\n|\\Z)\", re.S)\n_wiki = re.compile(r\"(!?)\\[\\[([^\\[\\]\\n]+?)\\]\\]\")\n_mdlink = re.compile(r\"(?<!!)\\[[^\\]\\n]*\\]\\(([^)\\s]+?\\.md)(?:#[^)]*)?\\)\")\n_task = re.compile(r\"^[ \\t]*[-*+] \\[([ xX])\\][ \\t]\", re.M)\n_img = re.compile(r\"!\\[[^\\]\\n]*\\]\\([^)\\n]+\\)|!\\[\\[[^\\]\\n]+\\.(?:png|jpe?g|gif|webp|svg|heic|avif|bmp)(?:\\|[^\\]]*)?\\]\\]\", re.I)\n_tagch = re.compile(r\"[\\w\\-/]\", re.U)\n_heading = re.compile(r\"^(#{1,6})[ \\t]+(.+?)[ \\t#]*$\", re.M)\n\n\ndef 코드빼기(text):\n    text = _fence.sub(lambda m: \"\\n\" * m.group(0).count(\"\\n\"), text)\n    return _inline_code.sub(\" \", text)\n\n\ndef 머리속성(text):\n    \"\"\"(속성 dict, 본문). 옵시디언 properties 의 간단한 경우만 읽는다.\"\"\"\n    m = _front.match(text)\n    if not m:\n        return {}, text\n    props, key = {}, None\n    for line in m.group(1).split(\"\\n\"):\n        if re.match(r\"^\\s+-\\s+\", line) and key:\n            props.setdefault(key, [])\n            if isinstance(props[key], list):\n                props[key].append(line.split(\"-\", 1)[1].strip().strip(\"'\\\"\"))\n            continue\n        if \":\" in line:\n            key, v = line.split(\":\", 1)\n            key, v = key.strip(), v.strip()\n            if v.startswith(\"[\") and v.endswith(\"]\"):\n                props[key] = [x.strip().strip(\"'\\\"\") for x in v[1:-1].split(\",\") if x.strip()]\n            elif v:\n                props[key] = v.strip(\"'\\\"\")\n            else:\n                props[key] = []\n    return props, text[m.end():]\n\n\ndef 태그찾기(text):\n    \"\"\"본문의 #태그. 베어의 #여러 단어 태그# 도 받는다. 숫자만(#1)은 아니다.\"\"\"\n    out = []\n    i, n = 0, len(text)\n    while True:\n        i = text.find(\"#\", i)\n        if i < 0:\n            break\n        if i > 0 and not (text[i - 1].isspace() or text[i - 1] in \"(（「\\\"'\"):\n            i += 1; continue\n        j = i + 1\n        while j < n and (_tagch.match(text[j]) or text[j] == \"_\"):\n            j += 1\n        word = text[i + 1:j]\n        if not word or re.fullmatch(r\"[\\d/\\-_]+\", word):\n            i = j if j > i + 1 else i + 1; continue\n        end = j\n        if j < n and text[j] == \" \":\n            k = j\n            while k < n and text[k] not in \"\\n#\":\n                k += 1\n            if (k < n and text[k] == \"#\" and text[k - 1] != \" \" and k - i < 60\n                    and \"[\" not in text[j:k] and \"]\" not in text[j:k]\n                    and (k + 1 >= n or text[k + 1].isspace() or text[k + 1] in \".,!?)\")):\n                word = text[i + 1:k]; end = k + 1\n        out.append(word.strip(\"/\"))\n        i = end\n    return out\n\n\ndef 링크풀기(raw):\n    \"\"\"'노트#제목|별칭' → '노트'\"\"\"\n    return raw.split(\"|\", 1)[0].split(\"#\", 1)[0].strip()\n\n\ndef 뽑기(text):\n    props, body = 머리속성(text)\n    plain = 코드빼기(body)\n    # 제목줄(# 제목)을 태그로 읽지 않게: '#' 뒤에 빈칸이 있으면 이미 태그가 아니다.\n    tags = 태그찾기(plain)\n    ptags = props.get(\"tags\") or props.get(\"tag\") or []\n    if isinstance(ptags, str):\n        ptags = [x.strip() for x in re.split(r\"[,\\s]+\", ptags) if x.strip()]\n    tags += [t.lstrip(\"#\") for t in ptags if t]\n    seen, tags2 = set(), []\n    for t in tags:\n        k = t.lower()\n        if k not in seen:\n            seen.add(k); tags2.append(t)\n    links = []\n    for m in _wiki.finditer(plain):\n        tgt = 링크풀기(m.group(2))\n        if tgt:\n            links.append(tgt)\n    for m in _mdlink.finditer(plain):\n        links.append(re.sub(r\"\\.md$\", \"\", m.group(1).replace(\"%20\", \" \")))\n    tasks = _task.findall(plain)\n    open_ = sum(1 for x in tasks if x == \" \")\n    done = len(tasks) - open_\n    # 미리보기 한두 줄: 기호를 걷어낸 첫 글\n    snip = []\n    for line in body.split(\"\\n\"):\n        s = line.strip()\n        if not s or s.startswith(\"```\") or re.fullmatch(r\"[-*_=]{3,}\", s):\n            continue\n        if s.startswith(\"|\"):\n            if re.fullmatch(r\"[|\\s:\\-]+\", s):\n                continue\n            s = \" · \".join(c.strip() for c in s.strip(\"|\").split(\"|\") if c.strip())\n        s = re.sub(r\"^#{1,6}\\s+\", \"\", s)\n        s = re.sub(r\"^>\\s*(\\[!\\w+\\]\\s*)?\", \"\", s)\n        s = re.sub(r\"^[-*+]\\s+(\\[[ xX]\\]\\s+)?|^\\d+\\.\\s+\", \"\", s)\n        s = re.sub(r\"!\\[\\[[^\\]]*\\]\\]|!\\[[^\\]]*\\]\\([^)]*\\)\", \"\", s)\n        s = re.sub(r\"\\[\\[([^\\]|]*\\|)?([^\\]]*)\\]\\]\", r\"\\2\", s)\n        s = re.sub(r\"\\[([^\\]]*)\\]\\([^)]*\\)\", r\"\\1\", s)\n        s = re.sub(r\"(\\*\\*|__|==|~~|\\*|`)\", \"\", s)\n        s = re.sub(r\"\\[\\^[^\\]\\s]+\\](:\\s*)?\", \"\", s)\n        if s:\n            snip.append(s)\n        if sum(len(x) for x in snip) > 220:\n            break\n    # 목록 썸네일용 첫 사진 (베어처럼)\n    첫사진 = \"\"\n    m = _img.search(body)\n    if m:\n        t = m.group(0)\n        첫사진 = (re.search(r\"\\]\\(([^)\\s]+)\", t) or re.search(r\"!\\[\\[([^\\]|]+)\", t)).group(1)\n    글자 = len(re.sub(r\"\\s\", \"\", body))\n    단어 = len(re.findall(r\"\\S+\", body))\n    return {\n        \"tags\": tags2, \"links\": links, \"todo\": open_, \"done\": done,\n        \"images\": bool(첫사진), \"img\": 첫사진, \"snippet\": \" \".join(snip)[:240],\n        \"chars\": 글자, \"words\": 단어, \"props\": props,\n    }\n\n\ndef 제목들(text):\n    \"\"\"개요(Outline)에 쓸 제목 목록 [(줄번호, 단계, 글)] — 코드 블록 안은 뺀다.\"\"\"\n    _, body = 머리속성(text)\n    off = text.count(\"\\n\", 0, len(text) - len(body))\n    plain = _fence.sub(lambda m: \"\\n\" * m.group(0).count(\"\\n\"), body)\n    out = []\n    for i, line in enumerate(plain.split(\"\\n\")):\n        m = re.match(r\"^(#{1,6})[ \\t]+(.+?)[ \\t#]*$\", line)\n        if m:\n            out.append([i + off + 1, len(m.group(1)), m.group(2)])\n    return out\n\n\n# 파일 이름에는 '/' 를 못 쓴다 — 모양이 같은 '∕'(U+2215)로 저장하고 제목에서는 '/' 로 되돌린다.\n빗금 = \"\\u2215\"\n\n\ndef 제목으로(이름):\n    return 이름.replace(빗금, \"/\")\n\n\ndef 파일이름(제목):\n    s = NFC(제목 or \"\").strip().replace(\"/\", 빗금)\n    s = re.sub(r'[\\\\:*?\"<>|\\n\\r\\t]', \" \", s)\n    s = re.sub(r\"\\s+\", \" \", s).strip().lstrip(\".\")\n    return s[:120] or \"제목 없음\"\n\n\n# ── 보관함 ─────────────────────────────────────────────────────────────\n\nclass 보관함:\n    def __init__(self, 경로):\n        self.root = os.path.abspath(경로)\n        os.makedirs(self.root, exist_ok=True)\n        self.app = os.path.join(self.root, 앱폴더)\n        os.makedirs(os.path.join(self.app, \"기록\"), exist_ok=True)\n        self.lock = threading.RLock()\n        self.notes = {}        # 경로(NFC, '/') → 목록 정보\n        self.texts = {}        # 경로 → 본문\n        self.files = {}        # 경로 → 첨부 등 노트 아닌 파일 (크기, 시각)\n        self.folders = set()\n        self._실제 = {}        # NFC 경로 → 디스크 상대 경로\n        self.rev = 0\n        self.state = self._상태읽기()\n        self.settings = {**기본설정, **{k: v for k, v in self.state.get(\"설정\", {}).items() if k in 기본설정}}\n        self.journals = self.state[\"일기종류\"] if isinstance(self.state.get(\"일기종류\"), list) else [dict(j) for j in 기본_일기종류]\n        self.일정공급 = None        # (날짜, 일기종류) → 마크다운 목록. iCloud 를 붙이면 서버가 넣는다\n        self.훑기()\n\n    # ── 상태 파일 ──\n    def _상태파일(self):\n        return os.path.join(self.app, \"상태.json\")\n\n    def _상태읽기(self):\n        try:\n            with open(self._상태파일(), encoding=\"utf-8\") as f:\n                s = json.load(f)\n        except Exception:\n            s = {}\n        s.setdefault(\"노트\", {})\n        s.setdefault(\"휴지통\", {})\n        return s\n\n    def _상태쓰기(self):\n        p = self._상태파일()\n        tmp = p + \".tmp\"\n        with open(tmp, \"w\", encoding=\"utf-8\") as f:\n            json.dump(self.state, f, ensure_ascii=False, indent=1)\n        os.replace(tmp, p)\n\n    def _메타(self, path):\n        return self.state[\"노트\"].setdefault(path, {})\n\n    def 일기종류바꾸기(self, 목록):\n        out, seen = [], set()\n        for j in 목록 or []:\n            name = 파일이름(str(j.get(\"이름\", \"\"))).strip()\n            if not name or name in seen:\n                continue\n            seen.add(name)\n            folder = self.안전(j.get(\"폴더\") or (\"일기/\" + name))\n            tpl = str(j.get(\"템플릿\") or \"\").strip()\n            cals = [str(c).strip() for c in (j.get(\"캘린더\") or []) if str(c).strip()]\n            out.append({\"이름\": name, \"폴더\": folder, \"템플릿\": tpl, \"캘린더\": cals})\n        with self.lock:\n            self.journals = out\n            self.state[\"일기종류\"] = out\n            self._상태쓰기()\n            self.rev += 1\n        return out\n\n    def 순서(self):\n        o = self.state.get(\"순서\") or {}\n        return {\"folders\": o.get(\"폴더\", []), \"tags\": o.get(\"태그\", []), \"locked\": o.get(\"잠금\", True)}\n\n    def 순서바꾸기(self, d):\n        글목록 = lambda v: [str(x) for x in (v or []) if isinstance(x, str)][:5000]\n        with self.lock:\n            o = self.state.setdefault(\"순서\", {})\n            if \"folders\" in d:\n                o[\"폴더\"] = 글목록(d[\"folders\"])\n            if \"tags\" in d:\n                o[\"태그\"] = 글목록(d[\"tags\"])\n            if \"locked\" in d:\n                o[\"잠금\"] = bool(d[\"locked\"])\n            self._상태쓰기()\n            self.rev += 1\n        return self.순서()\n\n    def 일기종류(self, 이름=None):\n        if 이름:\n            for j in self.journals:\n                if j[\"이름\"] == 이름:\n                    return j\n            raise ValueError(\"없는 일기 종류: %s\" % 이름)\n        if not self.journals:\n            raise ValueError(\"일기 종류가 없습니다\")\n        return self.journals[0]\n\n    def 설정바꾸기(self, 값):\n        with self.lock:\n            for k, v in 값.items():\n                if k in 기본설정:\n                    self.settings[k] = str(v).strip().strip(\"/\")\n            self.state[\"설정\"] = {k: self.settings[k] for k in 기본설정}\n            self._상태쓰기()\n            for n in self.notes.values():\n                n[\"tpl\"] = self._템플릿인가(n[\"folder\"])\n            self.rev += 1\n        return self.settings\n\n    # ── 경로 ──\n    def 안전(self, rel, 숨김허용=False):\n        rel = NFC(str(rel or \"\")).replace(\"\\\\\", \"/\").strip(\"/\")\n        parts = [p for p in rel.split(\"/\") if p not in (\"\", \".\")]\n        if any(p == \"..\" for p in parts):\n            raise ValueError(\"경로가 올바르지 않습니다\")\n        if not 숨김허용 and any(p.startswith(\".\") for p in parts):\n            raise ValueError(\"숨은 폴더는 다룰 수 없습니다\")\n        return \"/\".join(parts)\n\n    def 디스크(self, rel):\n        rel = self._실제.get(rel, rel)\n        return os.path.join(self.root, *rel.split(\"/\")) if rel else self.root\n\n    @staticmethod\n    def 판(st):\n        return \"%d-%d\" % (st.st_mtime_ns, st.st_size)\n\n    # ── 훑기: 바깥(옵시디언·SMB)에서 바뀐 것도 여기서 잡힌다 ──\n    def 훑기(self):\n        notes, files, folders, real = {}, {}, set(), {}\n        for dirpath, dirnames, filenames in os.walk(self.root):\n            dirnames[:] = [d for d in dirnames if not d.startswith(\".\")]\n            relroot = os.path.relpath(dirpath, self.root)\n            relroot = \"\" if relroot == \".\" else relroot.replace(os.sep, \"/\")\n            if relroot:\n                folders.add(NFC(relroot))\n            for fn in filenames:\n                if fn.startswith(\".\") or fn.endswith(\".tmp\"):\n                    continue\n                diskrel = (relroot + \"/\" + fn) if relroot else fn\n                rel = NFC(diskrel)\n                try:\n                    st = os.stat(os.path.join(dirpath, fn))\n                except OSError:\n                    continue\n                real[rel] = diskrel\n                if fn.lower().endswith(노트확장자):\n                    notes[rel] = st\n                else:\n                    files[rel] = {\"size\": st.st_size, \"mtime\": st.st_mtime}\n        changed = False\n        with self.lock:\n            self._실제 = real\n            for rel, st in notes.items():\n                cur = self.notes.get(rel)\n                ver = self.판(st)\n                if cur and cur[\"ver\"] == ver:\n                    continue\n                try:\n                    with open(self.디스크(rel), encoding=\"utf-8\", errors=\"replace\") as f:\n                        text = f.read()\n                except OSError:\n                    continue\n                self._넣기(rel, text, st)\n                changed = True\n            for rel in list(self.notes):\n                if rel not in notes:\n                    self.notes.pop(rel, None); self.texts.pop(rel, None); changed = True\n            if set(files) != set(self.files) or folders != self.folders:\n                changed = True\n            self.files, self.folders = files, folders\n            if changed:\n                self.rev += 1\n        return changed\n\n    def _넣기(self, rel, text, st=None):\n        if st is None:\n            st = os.stat(self.디스크(rel))\n        info = 뽑기(text)\n        meta = self._메타(rel)\n        if \"만든날\" not in meta:\n            meta[\"만든날\"] = min(st.st_mtime, getattr(st, \"st_birthtime\", st.st_mtime))\n        folder, _, name = rel.rpartition(\"/\")\n        title = 제목으로(re.sub(r\"\\.(md|markdown)$\", \"\", name, flags=re.I))\n        info.pop(\"props\", None)\n        self.notes[rel] = {\n            \"path\": rel, \"title\": title, \"folder\": folder,\n            \"mtime\": st.st_mtime, \"ctime\": meta[\"만든날\"], \"size\": st.st_size,\n            \"ver\": self.판(st), \"pinned\": bool(meta.get(\"고정\")), \"archived\": bool(meta.get(\"보관\")),\n            \"readonly\": bool(meta.get(\"읽기전용\")),\n            \"tpl\": self._템플릿인가(folder),\n            **info,\n        }\n        self.texts[rel] = text\n\n    def _템플릿인가(self, folder):\n        tf = (self.settings.get(\"템플릿폴더\") if hasattr(self, \"settings\") else \"\") or \"\"\n        return bool(tf) and (folder == tf or folder.startswith(tf + \"/\"))\n\n    # ── 목록 ──\n    def 목록(self):\n        with self.lock:\n            tags = {}\n            for n in self.notes.values():\n                if n[\"archived\"] or n.get(\"tpl\") or n[\"folder\"].split(\"/\")[0] == \"블로그 초안\":\n                    continue\n                for t in n[\"tags\"]:\n                    tags[t] = tags.get(t, 0) + 1\n            return {\n                \"rev\": self.rev,\n                \"notes\": sorted(self.notes.values(), key=lambda n: -n[\"mtime\"]),\n                \"folders\": sorted(self.folders),\n                \"tags\": tags,\n                \"trash\": len(self.state[\"휴지통\"]),\n                \"settings\": self.settings,\n                \"journals\": self.journals,\n                \"order\": self.순서(),\n                \"attachments\": len(self.files),\n            }\n\n    # ── 이름으로 노트 찾기 (옵시디언 방식: 파일 이름이 같으면 짧은 경로가 이긴다) ──\n    def 찾기(self, 이름):\n        이름 = NFC(링크풀기(이름 or \"\")).strip()\n        if not 이름:\n            return None\n        k = 이름.lower()\n        if k.endswith(\".md\"):\n            k = k[:-3]\n        with self.lock:\n            if 이름 in self.notes:\n                return 이름\n            hits = []\n            for rel, n in self.notes.items():\n                low = rel.lower()[:-3] if rel.lower().endswith(\".md\") else rel.lower()\n                if low == k or n[\"title\"].lower() == k or low.endswith(\"/\" + k):\n                    hits.append(rel)\n            hits.sort(key=lambda r: (r.count(\"/\"), len(r)))\n            return hits[0] if hits else None\n\n    def 파일찾기(self, 이름):\n        \"\"\"![[그림.png]] 처럼 이름만 적힌 첨부를 찾는다.\"\"\"\n        이름 = NFC(이름).replace(\"\\\\\", \"/\").strip(\"/\")\n        with self.lock:\n            if 이름 in self.files or 이름 in self.notes:\n                return 이름\n            base = 이름.rsplit(\"/\", 1)[-1].lower()\n            hits = [r for r in self.files if r.rsplit(\"/\", 1)[-1].lower() == base]\n            hits.sort(key=lambda r: (r.count(\"/\"), len(r)))\n            return hits[0] if hits else None\n\n    # ── 읽기 ──\n    def 읽기(self, rel):\n        rel = self.안전(rel)\n        with self.lock:\n            if rel not in self.notes:\n                self.훑기()\n            if rel not in self.notes:\n                raise 없음(rel)\n            n = self.notes[rel]\n            return {\"path\": rel, \"text\": self.texts[rel], \"ver\": n[\"ver\"], \"meta\": n,\n                    \"outline\": 제목들(self.texts[rel])}\n\n    # ── 쓰기 ──\n    def _원자쓰기(self, rel, text):\n        p = self.디스크(rel)\n        os.makedirs(os.path.dirname(p), exist_ok=True)\n        tmp = p + \".tmp\"\n        with open(tmp, \"w\", encoding=\"utf-8\", newline=\"\\n\") as f:\n            f.write(text)\n        os.replace(tmp, p)\n        self._실제.setdefault(rel, rel)\n\n    def 저장(self, rel, text, base=None, 기기=\"\", 강제=False):\n        rel = self.안전(rel)\n        if not rel.lower().endswith(노트확장자):\n            raise ValueError(\"노트 파일이 아닙니다\")\n        with self.lock:\n            cur = self.notes.get(rel)\n            if cur and base and cur[\"ver\"] != base and not 강제:\n                # 디스크가 진짜로 바뀌었나 한 번 더 본다(같은 내용이면 충돌이 아니다)\n                if self.texts.get(rel) != text:\n                    raise 충돌(self.texts.get(rel, \"\"), cur[\"ver\"])\n            if cur and self.texts.get(rel) == text:\n                return cur\n            if cur:\n                self._기록남기기(rel, self.texts.get(rel, \"\"), 기기)\n            self._원자쓰기(rel, text)\n            self._넣기(rel, text)\n            m = self._메타(rel)\n            m[\"마지막기기\"] = 기기\n            self._상태쓰기()\n            self.folders.update(self._상위폴더들(rel))\n            self.rev += 1\n            return self.notes[rel]\n\n    def _상위폴더들(self, rel):\n        parts = rel.split(\"/\")[:-1]\n        return {\"/\".join(parts[:i + 1]) for i in range(len(parts))}\n\n    def 새이름(self, folder, 제목, 확장자=\".md\"):\n        folder = self.안전(folder)\n        base = 파일이름(제목)\n        with self.lock:\n            for i in range(1, 1000):\n                name = base if i == 1 else \"%s %d\" % (base, i)\n                rel = (folder + \"/\" if folder else \"\") + name + 확장자\n                if rel not in self.notes and rel not in self.files and not os.path.exists(self.디스크(rel)):\n                    return rel\n        raise ValueError(\"이름을 정하지 못했습니다\")\n\n    def 만들기(self, folder, 제목, text=\"\", 기기=\"\"):\n        rel = self.새이름(folder, 제목)\n        with self.lock:\n            self._원자쓰기(rel, text)\n            self._넣기(rel, text)\n            self._메타(rel)[\"만든날\"] = time.time()\n            self._넣기(rel, text)\n            self._상태쓰기()\n            self.folders.update(self._상위폴더들(rel))\n            self.rev += 1\n        return rel\n\n    # ── 이름 바꾸기·옮기기 (다른 노트의 [[링크]] 도 같이 고친다) ──\n    def 옮기기(self, rel, 새경로, 링크고치기=True, 기기=\"\"):\n        rel, 새경로 = self.안전(rel), self.안전(새경로)\n        if not 새경로.lower().endswith(노트확장자):\n            새경로 += \".md\"\n        if rel == 새경로:\n            return rel\n        with self.lock:\n            if rel not in self.notes:\n                raise 없음(rel)\n            if 새경로 in self.notes or os.path.exists(self.디스크(새경로)):\n                if 새경로.lower() != rel.lower():\n                    raise ValueError(\"같은 이름의 노트가 이미 있습니다\")\n            old_title = self.notes[rel][\"title\"]\n            src = self.디스크(rel)\n            dst = os.path.join(self.root, *새경로.split(\"/\"))\n            os.makedirs(os.path.dirname(dst), exist_ok=True)\n            os.replace(src, dst)\n            self._실제.pop(rel, None); self._실제[새경로] = 새경로\n            text = self.texts.pop(rel); self.notes.pop(rel)\n            meta = self.state[\"노트\"].pop(rel, {})\n            self.state[\"노트\"][새경로] = meta\n            self._넣기(새경로, text)\n            self.folders.update(self._상위폴더들(새경로))\n            new_title = self.notes[새경로][\"title\"]\n            고친수 = 0\n            if 링크고치기 and new_title != old_title:\n                고친수 = self._링크바꾸기(old_title, new_title, rel, 새경로, 기기)\n            self._상태쓰기()\n            self.rev += 1\n            return 새경로, 고친수\n\n    def _링크바꾸기(self, old, new, oldrel, newrel, 기기):\n        oldkey = old.lower()\n        oldpath = oldrel[:-3].lower() if oldrel.lower().endswith(\".md\") else oldrel.lower()\n        newpath = newrel[:-3] if newrel.lower().endswith(\".md\") else newrel\n\n        def 바꿈(m):\n            bang, inner = m.group(1), m.group(2)\n            tgt = inner.split(\"|\", 1)[0]\n            name, hash_, rest = tgt.partition(\"#\")\n            k = name.strip().lower()\n            if k == oldkey:\n                nn = new\n            elif k == oldpath:\n                nn = newpath\n            else:\n                return m.group(0)\n            tail = (hash_ + rest) if hash_ else \"\"\n            alias = inner[len(tgt):]\n            return \"%s[[%s%s%s]]\" % (bang, nn, tail, alias)\n\n        n = 0\n        for rel in list(self.notes):\n            text = self.texts[rel]\n            if \"[[\" not in text:\n                continue\n            new_text = _wiki.sub(바꿈, text)\n            if new_text != text:\n                self._기록남기기(rel, text, 기기, 강제=True)\n                self._원자쓰기(rel, new_text)\n                self._넣기(rel, new_text)\n                n += 1\n        return n\n\n    def 태그바꾸기(self, old, new, 기기=\"\"):\n        \"\"\"#옛태그 → #새태그. 하위 태그(#옛태그/아래)도 같이 바뀐다.\"\"\"\n        old, new = old.strip(\"#/ \"), new.strip(\"#/ \")\n        if not old or not new:\n            raise ValueError(\"태그 이름이 비었습니다\")\n        tok = lambda t: \"#\" + t + (\"#\" if \" \" in t else \"\")\n        if \" \" in old:\n            pat = re.compile(r\"(?:(?<=^)|(?<=[\\s(（「\\\"']))#\" + re.escape(old) + \"#\", re.M)\n            sub = lambda m: tok(new)\n        else:\n            pat = re.compile(r\"(?:(?<=^)|(?<=[\\s(（「\\\"']))#\" + re.escape(old) + r\"(?=/|[^\\w\\-/]|$)\", re.M)\n            sub = lambda m: \"#\" + new if \" \" not in new else tok(new)\n        n = 0\n        with self.lock:\n            for rel in list(self.notes):\n                text = self.texts[rel]\n                if \"#\" + old not in text:\n                    continue\n                new_text = pat.sub(sub, text)\n                if new_text != text:\n                    self._기록남기기(rel, text, 기기, 강제=True)\n                    self._원자쓰기(rel, new_text)\n                    self._넣기(rel, new_text)\n                    n += 1\n            self.rev += 1\n        return n\n\n    # ── 고정·보관 ──\n    def 표시(self, rel, 이름, 켜기):\n        rel = self.안전(rel)\n        with self.lock:\n            if rel not in self.notes:\n                raise 없음(rel)\n            m = self._메타(rel)\n            if 켜기:\n                m[이름] = True\n            else:\n                m.pop(이름, None)\n            self.notes[rel][\"pinned\"] = bool(m.get(\"고정\"))\n            self.notes[rel][\"archived\"] = bool(m.get(\"보관\"))\n            self.notes[rel][\"readonly\"] = bool(m.get(\"읽기전용\"))\n            self._상태쓰기()\n            self.rev += 1\n\n    # ── 휴지통 ──\n    def 버리기(self, rel, 기기=\"\"):\n        rel = self.안전(rel)\n        with self.lock:\n            if rel not in self.notes and rel not in self.files:\n                raise 없음(rel)\n            stamp = datetime.now().strftime(\"%Y%m%d-%H%M%S\")\n            dst_rel = \"%s/%s/%s\" % (휴지통, stamp, rel)\n            dst = os.path.join(self.root, *dst_rel.split(\"/\"))\n            os.makedirs(os.path.dirname(dst), exist_ok=True)\n            os.replace(self.디스크(rel), dst)\n            meta = self.state[\"노트\"].pop(rel, {})\n            n = self.notes.pop(rel, None)\n            self.texts.pop(rel, None); self.files.pop(rel, None); self._실제.pop(rel, None)\n            self.state[\"휴지통\"][dst_rel] = {\n                \"원래\": rel, \"버린날\": time.time(), \"메타\": meta,\n                \"제목\": n[\"title\"] if n else rel.rsplit(\"/\", 1)[-1],\n                \"미리보기\": n[\"snippet\"] if n else \"\",\n            }\n            self._상태쓰기()\n            self.rev += 1\n            return dst_rel\n\n    def 휴지통목록(self):\n        with self.lock:\n            out = [{\"id\": k, **v} for k, v in self.state[\"휴지통\"].items()]\n        return sorted(out, key=lambda x: -x[\"버린날\"])\n\n    def 휴지통읽기(self, tid):\n        tid = self.안전(tid, 숨김허용=True)\n        if not tid.startswith(휴지통 + \"/\"):\n            raise ValueError(\"휴지통 항목이 아닙니다\")\n        with open(os.path.join(self.root, *tid.split(\"/\")), encoding=\"utf-8\", errors=\"replace\") as f:\n            return f.read()\n\n    def 되살리기(self, tid):\n        tid = self.안전(tid, 숨김허용=True)\n        with self.lock:\n            item = self.state[\"휴지통\"].get(tid)\n            if not item:\n                raise 없음(tid)\n            src = os.path.join(self.root, *tid.split(\"/\"))\n            want = item[\"원래\"]\n            if want in self.notes or os.path.exists(self.디스크(want)):\n                folder, _, name = want.rpartition(\"/\")\n                stem, dot, ext = name.rpartition(\".\")\n                want = self.새이름(folder, stem or name, \".\" + ext if dot else \"\")\n            dst = os.path.join(self.root, *want.split(\"/\"))\n            os.makedirs(os.path.dirname(dst), exist_ok=True)\n            os.replace(src, dst)\n            self._빈폴더치우기(os.path.dirname(src), os.path.join(self.root, 휴지통))\n            self.state[\"휴지통\"].pop(tid)\n            if item.get(\"메타\"):\n                self.state[\"노트\"][want] = item[\"메타\"]\n            self._상태쓰기()\n        self.훑기()\n        return want\n\n    def 영구삭제(self, tid=None):\n        with self.lock:\n            ids = [self.안전(tid, 숨김허용=True)] if tid else list(self.state[\"휴지통\"])\n            for k in ids:\n                if not k.startswith(휴지통 + \"/\"):\n                    continue\n                p = os.path.join(self.root, *k.split(\"/\"))\n                try:\n                    os.remove(p)\n                except OSError:\n                    pass\n                self._빈폴더치우기(os.path.dirname(p), os.path.join(self.root, 휴지통))\n                self.state[\"휴지통\"].pop(k, None)\n            self._상태쓰기()\n            self.rev += 1\n            return len(ids)\n\n    def _빈폴더치우기(self, d, 멈출곳):\n        d, 멈출곳 = os.path.abspath(d), os.path.abspath(멈출곳)\n        while d.startswith(멈출곳) and d != 멈출곳:\n            try:\n                os.rmdir(d)\n            except OSError:\n                break\n            d = os.path.dirname(d)\n\n    # ── 폴더 ──\n    def 폴더만들기(self, rel):\n        rel = self.안전(rel)\n        if not rel:\n            raise ValueError(\"폴더 이름이 비었습니다\")\n        os.makedirs(self.디스크(rel), exist_ok=True)\n        with self.lock:\n            self.folders.update(self._상위폴더들(rel + \"/x\"))\n            self.rev += 1\n        return rel\n\n    def 폴더옮기기(self, rel, 새경로):\n        rel, 새경로 = self.안전(rel), self.안전(새경로)\n        if not rel or not 새경로:\n            raise ValueError(\"폴더 이름이 비었습니다\")\n        if os.path.exists(self.디스크(새경로)):\n            raise ValueError(\"같은 이름의 폴더가 이미 있습니다\")\n        with self.lock:\n            os.makedirs(os.path.dirname(os.path.join(self.root, *새경로.split(\"/\"))), exist_ok=True)\n            os.replace(self.디스크(rel), os.path.join(self.root, *새경로.split(\"/\")))\n            pre = rel + \"/\"\n            for k in list(self.state[\"노트\"]):\n                if k.startswith(pre):\n                    self.state[\"노트\"][새경로 + \"/\" + k[len(pre):]] = self.state[\"노트\"].pop(k)\n            self.notes.clear(); self.texts.clear()\n            self._상태쓰기()\n        self.훑기()\n        return 새경로\n\n    def 폴더지우기(self, rel):\n        \"\"\"안에 든 노트는 휴지통으로 보내고 폴더를 지운다.\"\"\"\n        rel = self.안전(rel)\n        if not rel:\n            raise ValueError(\"맨 위 폴더는 지울 수 없습니다\")\n        with self.lock:\n            pre = rel + \"/\"\n            for k in [k for k in list(self.notes) + list(self.files) if k.startswith(pre)]:\n                self.버리기(k)\n            shutil.rmtree(self.디스크(rel), ignore_errors=True)\n            self.folders = {f for f in self.folders if f != rel and not f.startswith(pre)}\n            self.rev += 1\n\n    # ── 첨부 ──\n    def 첨부저장(self, 이름, data):\n        이름 = 파일이름(이름.rsplit(\"/\", 1)[-1]) or \"첨부\"\n        stem, dot, ext = 이름.rpartition(\".\")\n        if not dot:\n            stem, ext = 이름, \"bin\"\n        stamp = datetime.now().strftime(\"%Y%m%d-%H%M%S\")\n        if stem.lower() in (\"image\", \"img\", \"paste\", \"pasted image\", \"screenshot\", \"스크린샷\"):\n            stem = \"붙여넣기 \" + stamp\n        folder = self.settings.get(\"첨부폴더\", \"첨부\")\n        rel = self.새이름(folder, stem, \".\" + ext.lower())\n        p = os.path.join(self.root, *rel.split(\"/\"))\n        os.makedirs(os.path.dirname(p), exist_ok=True)\n        with open(p, \"wb\") as f:\n            f.write(data)\n        with self.lock:\n            self.files[rel] = {\"size\": len(data), \"mtime\": time.time()}\n            self._실제[rel] = rel\n            self.folders.update(self._상위폴더들(rel))\n            self.rev += 1\n        return rel\n\n    # ── 버전 기록 ──\n    def _기록폴더(self, rel):\n        h = hashlib.sha1(rel.encode(\"utf-8\")).hexdigest()[:16]\n        return os.path.join(self.app, \"기록\", h)\n\n    def _기록남기기(self, rel, text, 기기=\"\", 강제=False):\n        \"\"\"고치기 전 내용을 남긴다. 같은 기기에서 연달아 고치면 10분에 한 번만.\"\"\"\n        if not text:\n            return\n        d = self._기록폴더(rel)\n        os.makedirs(d, exist_ok=True)\n        meta = self._메타(rel)\n        last = meta.get(\"기록시각\", 0)\n        if not 강제 and 기기 and meta.get(\"마지막기기\") == 기기 and time.time() - last < 600:\n            return\n        name = datetime.now().strftime(\"%Y%m%d-%H%M%S\") + \".md\"\n        with open(os.path.join(d, name), \"w\", encoding=\"utf-8\", newline=\"\\n\") as f:\n            f.write(text)\n        with open(os.path.join(d, \"경로.txt\"), \"w\", encoding=\"utf-8\") as f:\n            f.write(rel)\n        meta[\"기록시각\"] = time.time()\n        files = sorted(x for x in os.listdir(d) if x.endswith(\".md\"))\n        for old in files[:-200]:            # 노트 하나에 200판까지\n            try:\n                os.remove(os.path.join(d, old))\n            except OSError:\n                pass\n\n    def 기록목록(self, rel):\n        rel = self.안전(rel)\n        d = self._기록폴더(rel)\n        if not os.path.isdir(d):\n            return []\n        out = []\n        for x in sorted(os.listdir(d), reverse=True):\n            if not x.endswith(\".md\"):\n                continue\n            st = os.stat(os.path.join(d, x))\n            t = datetime.strptime(x[:-3], \"%Y%m%d-%H%M%S\")\n            out.append({\"id\": x[:-3], \"time\": t.timestamp(), \"size\": st.st_size})\n        return out\n\n    def 기록읽기(self, rel, hid):\n        rel = self.안전(rel)\n        if not re.fullmatch(r\"\\d{8}-\\d{6}\", hid or \"\"):\n            raise ValueError(\"기록 번호가 올바르지 않습니다\")\n        with open(os.path.join(self._기록폴더(rel), hid + \".md\"), encoding=\"utf-8\") as f:\n            return f.read()\n\n    # ── 일기 ──\n    def 일기경로(self, 날짜, 종류=None):\n        fmt = self.settings.get(\"일기제목형식\") or \"%Y-%m-%d\"\n        try:\n            name = 날짜.strftime(fmt)\n        except ValueError:\n            name = 날짜.strftime(\"%Y-%m-%d\")\n        folder = self.일기종류(종류)[\"폴더\"]\n        return (folder + \"/\" if folder else \"\") + 파일이름(name) + \".md\"\n\n    def 일기(self, 날짜, 만들기=True, 기기=\"\", 종류=None):\n        j = self.일기종류(종류)\n        rel = self.일기경로(날짜, j[\"이름\"])\n        with self.lock:\n            if rel in self.notes or not 만들기:\n                return rel, False\n            기본 = 기본_일기템플릿.get(j[\"이름\"], 기본_일기템플릿_공통)\n            text = self.템플릿적용(j.get(\"템플릿\", \"\"), 날짜.strftime(\"%Y-%m-%d\"), 날짜, 기본=기본, 일기=j)\n            self._원자쓰기(rel, text)\n            self._메타(rel)[\"만든날\"] = time.time()\n            self._넣기(rel, text)\n            self._상태쓰기()\n            self.folders.update(self._상위폴더들(rel))\n            self.rev += 1\n            return rel, True\n\n    def 템플릿목록(self):\n        folder = self.settings.get(\"템플릿폴더\", \"템플릿\")\n        pre = folder + \"/\" if folder else \"\"\n        with self.lock:\n            return sorted(n[\"path\"] for n in self.notes.values() if n[\"path\"].startswith(pre))\n\n    def 템플릿적용(self, rel, 제목=\"\", 날짜=None, 기본=\"\", 일기=None):\n        text = 기본\n        if rel:\n            try:\n                rel = self.안전(rel)\n                if rel in self.texts:\n                    text = self.texts[rel]\n            except ValueError:\n                pass\n        d = 날짜 or datetime.now()\n        now = datetime.now()\n        요일 = \"월화수목금토일\"[d.weekday()]\n\n        def 날짜형식(m):\n            fmt = m.group(1)\n            if not fmt:\n                return d.strftime(\"%Y-%m-%d\")\n            fmt = (fmt.replace(\"YYYY\", \"%Y\").replace(\"MM\", \"%m\").replace(\"DD\", \"%d\")\n                      .replace(\"HH\", \"%H\").replace(\"mm\", \"%M\").replace(\"dddd\", 요일 + \"요일\").replace(\"ddd\", 요일))\n            return d.strftime(fmt)\n        text = re.sub(r\"\\{\\{date(?::([^}]*))?\\}\\}\", 날짜형식, text)\n        text = text.replace(\"{{time}}\", now.strftime(\"%H:%M\"))\n        text = text.replace(\"{{title}}\", 제목 or \"\")\n        text = text.replace(\"{{요일}}\", 요일)\n        if \"{{일정}}\" in text:\n            일정 = \"\"\n            if self.일정공급:\n                try:\n                    일정 = self.일정공급(d, 일기)\n                except Exception:\n                    일정 = \"\"\n            text = text.replace(\"{{일정}}\", 일정 or \"- \")\n        text = text.replace(\"{{yesterday}}\", (d - timedelta(days=1)).strftime(\"%Y-%m-%d\"))\n        text = text.replace(\"{{tomorrow}}\", (d + timedelta(days=1)).strftime(\"%Y-%m-%d\"))\n        return text\n\n    # ── 백링크 ──\n    def 백링크(self, rel):\n        rel = self.안전(rel)\n        with self.lock:\n            if rel not in self.notes:\n                raise 없음(rel)\n            title = self.notes[rel][\"title\"]\n            linked, unlinked = [], []\n            pat = re.compile(re.escape(title), re.I) if len(title) >= 2 else None\n            for other, n in self.notes.items():\n                if other == rel:\n                    continue\n                text = self.texts[other]\n                hits = [l for l in n[\"links\"] if self.찾기(l) == rel]\n                lines = []\n                if hits:\n                    for i, line in enumerate(text.split(\"\\n\")):\n                        for m in _wiki.finditer(line):\n                            if self.찾기(m.group(2)) == rel:\n                                lines.append([i + 1, line.strip()[:200]]); break\n                    linked.append({\"path\": other, \"title\": n[\"title\"], \"lines\": lines[:5]})\n                elif pat and pat.search(text):\n                    for i, line in enumerate(text.split(\"\\n\")):\n                        if pat.search(line) and \"[[\" not in line:\n                            lines.append([i + 1, line.strip()[:200]])\n                    if lines:\n                        unlinked.append({\"path\": other, \"title\": n[\"title\"], \"lines\": lines[:3]})\n            return {\"linked\": linked, \"unlinked\": unlinked[:50]}\n\n    def 그래프(self):\n        with self.lock:\n            nodes, edges = [], []\n            idx = {}\n            for rel, n in self.notes.items():\n                idx[rel] = len(nodes)\n                nodes.append({\"id\": rel, \"title\": n[\"title\"], \"tags\": n[\"tags\"][:5], \"folder\": n[\"folder\"]})\n            missing = {}\n            for rel, n in self.notes.items():\n                for l in set(n[\"links\"]):\n                    tgt = self.찾기(l)\n                    if tgt and tgt != rel:\n                        edges.append([idx[rel], idx[tgt]])\n                    elif not tgt:\n                        if l not in missing:\n                            missing[l] = len(nodes)\n                            nodes.append({\"id\": \"\", \"title\": l, \"missing\": True})\n                        edges.append([idx[rel], missing[l]])\n            return {\"nodes\": nodes, \"edges\": edges}\n\n    # ── 찾기 ──\n    def 검색(self, q, limit=100, 보관포함=False):\n        \"\"\"베어식 검색어를 받는다.\n            낱말 낱말          둘 다 들어 있는 노트\n            \"붙은 말\"          그대로 붙어 있는 것\n            -낱말              빼기\n            #태그 / tag:태그   태그(하위 태그 포함)\n            folder:폴더 / path:\n            @todo @done @today @yesterday @last7days @pinned @untagged @tagged @images @archived\n            @date(2026-10) @date(2026-10-16)\n        \"\"\"\n        q = NFC(q or \"\").strip()\n        toks = re.findall(r'-?\"[^\"]*\"|\\S+', q)\n        terms, neg, tags, folders, flags, dates = [], [], [], [], set(), []\n        for tk in toks:\n            neg_ = tk.startswith(\"-\") and len(tk) > 1\n            raw = tk[1:] if neg_ else tk\n            if raw.startswith('\"') and raw.endswith('\"'):\n                raw = raw[1:-1]\n                (neg if neg_ else terms).append(raw.lower()); continue\n            low = raw.lower()\n            if low.startswith(\"#\") and len(low) > 1:\n                tags.append((low[1:].rstrip(\"#\"), neg_))\n            elif low.startswith(\"tag:\"):\n                tags.append((low[4:].lstrip(\"#\"), neg_))\n            elif low.startswith((\"folder:\", \"path:\")):\n                folders.append((low.split(\":\", 1)[1].strip(\"/\"), neg_))\n            elif re.fullmatch(r\"@date\\((\\d{4}(-\\d{2}){0,2})\\)\", low):\n                dates.append(re.fullmatch(r\"@date\\(([^)]*)\\)\", low).group(1))\n            elif low.startswith(\"@\") and len(low) > 1:\n                flags.add(low[1:])\n            else:\n                (neg if neg_ else terms).append(low)\n        if \"archived\" in flags:\n            보관포함 = True\n        now = datetime.now()\n        today = now.strftime(\"%Y-%m-%d\")\n        out = []\n        with self.lock:\n            for rel, n in self.notes.items():\n                if n[\"archived\"] and not 보관포함:\n                    continue\n                if \"archived\" in flags and not n[\"archived\"]:\n                    continue\n                text = self.texts[rel]\n                low = text.lower()\n                tl = n[\"title\"].lower()\n                ok = True\n                for t in terms:\n                    if t not in low and t not in tl:\n                        ok = False; break\n                if not ok:\n                    continue\n                if any(t in low or t in tl for t in neg):\n                    continue\n                ntags = [x.lower() for x in n[\"tags\"]]\n                for t, ng in tags:\n                    has = any(x == t or x.startswith(t + \"/\") for x in ntags)\n                    if has == ng:\n                        ok = False; break\n                if not ok:\n                    continue\n                for f, ng in folders:\n                    has = n[\"folder\"].lower() == f or n[\"folder\"].lower().startswith(f + \"/\")\n                    if has == ng:\n                        ok = False; break\n                if not ok:\n                    continue\n                md = datetime.fromtimestamp(n[\"mtime\"]).strftime(\"%Y-%m-%d\")\n                cd = datetime.fromtimestamp(n[\"ctime\"]).strftime(\"%Y-%m-%d\")\n                if \"todo\" in flags and (not n[\"todo\"] or n.get(\"tpl\")):\n                    continue\n                if \"done\" in flags and not n[\"done\"]:\n                    continue\n                if \"today\" in flags and today not in (md, cd):\n                    continue\n                if \"yesterday\" in flags:\n                    y = (now - timedelta(days=1)).strftime(\"%Y-%m-%d\")\n                    if y not in (md, cd):\n                        continue\n                if \"last7days\" in flags and n[\"mtime\"] < time.time() - 7 * 86400:\n                    continue\n                if \"pinned\" in flags and not n[\"pinned\"]:\n                    continue\n                if \"untagged\" in flags and n[\"tags\"]:\n                    continue\n                if \"tagged\" in flags and not n[\"tags\"]:\n                    continue\n                if \"images\" in flags and not n[\"images\"]:\n                    continue\n                if dates and not any(md.startswith(d) or cd.startswith(d) or n[\"title\"].startswith(d) for d in dates):\n                    continue\n                score = 0.0\n                snips = []\n                for t in terms:\n                    if t in tl:\n                        score += 10\n                    c = low.count(t)\n                    score += min(c, 10)\n                    i = low.find(t)\n                    if i >= 0 and len(snips) < 3:\n                        a = max(0, i - 40)\n                        b = min(len(text), i + len(t) + 80)\n                        s = text[a:b].replace(\"\\n\", \" \")\n                        snips.append((\"…\" if a > 0 else \"\") + s + (\"…\" if b < len(text) else \"\"))\n                score += n[\"mtime\"] / 1e10\n                if n[\"pinned\"]:\n                    score += 0.5\n                out.append({\"path\": rel, \"title\": n[\"title\"], \"score\": score, \"snips\": snips,\n                            \"mtime\": n[\"mtime\"], \"folder\": n[\"folder\"], \"tags\": n[\"tags\"]})\n        out.sort(key=lambda x: -x[\"score\"])\n        return out[:limit]\n", "/vault/베어처럼 쓰기.md": "쓰는 감각은 베어와 같게, 저장은 그냥 `.md` 파일로.\n\n## 글머리 · 들여쓰기\n* 빈칸까지 치면 바로 점이 돼요\n  * Tab 하면 하위 항목\n    * 단계마다 모양이 바뀌어요\n\n0) 번호는 `1.` 과 `0)` 둘 다\n1) 엔터를 치면 하나씩 올라가요\n\n## 할 일\n- [x] 리뷰 사진 고르기\n- [ ] 측정값 표로 정리\n- [ ] 썸네일 문구 정하기\n\n## 글자 모양\n**굵게** · *기울임* · ~밑줄~ · ==형광펜== · ~~취소선~~ · `코드`\n\n## 콜아웃 · 인용 · 표\n> [!tip] 팁\n> 서식 막대의 ⋮ 에서 콜아웃 종류를 고를 수 있어요.\n\n> 인용은 이렇게.\n\n| 기기 | 무게 | 배터리 |\n| --- | --- | --- |\n| 이어폰 A | 5.3g | 8시간 |\n| 이어폰 B | 4.9g | 6시간 |\n\n#사용법\n", "/vault/환영합니다 — 게스트판.md": "👋 **뮤직잇츠 노트**의 게스트판이에요. 베어처럼 쓰고, 옵시디언처럼 잇는 노트예요.\n\n> [!warning] 여기서 쓴 글은 저장되지 않아요\n> 이 브라우저 창 안에서만 살아 있어요. 새로고침하거나 창을 닫으면 처음 상태로 돌아가요. 마음껏 눌러 보세요.\n\n## 먼저 해 볼 것\n- [ ] 목록 위 **✎** 단추로 새 노트 만들기\n- [ ] [[베어처럼 쓰기]] 열어서 글머리·할 일·형광펜 써 보기\n- [ ] [[노트 잇기와 태그]] 에서 `[[` 쳐 보기\n- [ ] 달력에서 오늘 날짜를 두 번 눌러 **일기** 열기\n- [ ] ⌘O(윈도우 Ctrl+O)로 아무 노트나 빨리 열기\n\n## 진짜 앱에는 있고, 여기엔 없는 것\n- 맥·PC·폰 사이 자동 동기화(나스에 저장)\n- AI 요약, 아이클라우드 일정, Claude 커넥터\n- 백업과 버전 업데이트\n\n#시작\n", "/vault/노트 잇기와 태그.md": "`[[` 만 쳐도 노트 목록이 떠요. 예: [[소니 3세대 비교 글감]], [[에어팟 5 리뷰 체크리스트]]\n\n- 링크는 `[[노트#제목]]`, `[[노트|보일 말]]` 도 돼요\n- 오른쪽 ⓘ → **백링크** 에서 이 노트를 가리키는 노트를 볼 수 있어요\n- 노트 이름을 바꾸면 다른 노트의 링크도 같이 고쳐져요\n\n태그는 `#태그`, `#상위/하위`, 빈칸이 있으면 `#여러 단어#`\n\n#사용법 #블로그/글감\n", "/vault/템플릿/리뷰 글감.md": "# {{title}}\n\n{{date:YYYY-MM-DD}} ({{요일}}) 시작\n\n## 한 줄 결론\n- \n\n## 스펙 · 가격\n| 항목 | 내용 |\n| --- | --- |\n| 가격 |  |\n| 무게 |  |\n\n## 장점\n- \n\n## 이런 분은 거르세요\n- \n\n#블로그/글감\n", "/vault/글감/에어팟 5 리뷰 체크리스트.md": "- [x] 언박싱 사진\n- [ ] 노이즈 캔슬링 끄기 방법 캡처\n- [ ] 버즈4 프로와 착용감 비교\n- [ ] ==출시 며칠 만에 수령== 문구 넣기\n\n#블로그/글감 #애플\n", "/vault/글감/소니 3세대 비교 글감.md": "WF-1000XM4 · XM5 · XM6 를 다 갖고 있어서 나란히 비교하는 글.\n\n## 볼 것\n- 착용감 (무게 실측)\n- 노이즈 캔슬링 체감\n- 통화 품질 — 지하철에서 녹음\n- 배터리 실측\n\n## 구성 메모\n1. 결론부터 — 누구에게 어떤 걸 추천?\n2. 스펙 표 (해외가 vs 국내가 한 줄)\n3. 이런 분은 거르세요\n\n관련: [[에어팟 5 리뷰 체크리스트]]\n\n#블로그/글감 #소니\n", "/vault/Brain Dump/10월 Brain Dump.md": "머릿속에 떠오르는 걸 일단 다 적는 노트.\n\n- 서울레코드페어 예약 확인\n- 블로그 배너 SIDE B 카드 색 다시 보기\n- 노트 앱: 다크 모드 사이드바 색 한 번 더\n- 주말에 LP 정리\n\n#brain-dump\n"}, "router": "\"\"\"게스트판 — 노트서버.py 의 보관함 명령만 브라우저 안(Pyodide)에서 받는다. 보관함은 메모리라 새로고침하면 사라진다.\"\"\"\nimport json\nimport sys\nimport time\nfrom datetime import datetime, timedelta\n\nsys.path.insert(0, \"/app\")\nfrom 공용.보관함 import 보관함, 충돌, 없음, 파일이름  # noqa: E402\n\nV = 보관함(\"/vault\")\nV.일기종류바꾸기([{\"이름\": \"블로그\"}, {\"이름\": \"일상\"}])\nfor _p in (\"환영합니다 — 게스트판.md\",):\n    if _p in V.notes:\n        V.표시(_p, \"고정\", True)\n_어제 = datetime.now() - timedelta(days=1)\n_rel, _ = V.일기(_어제, True, \"\", \"블로그\")\nV.저장(_rel, V.texts[_rel].replace(\"## 쓴 글·올린 글\\n- \", \"## 쓴 글·올린 글\\n- 에어팟 5 노이즈 캔슬링 끄기 해결형 글 발행\")\n       .replace(\"## 글감\\n- \", \"## 글감\\n- 소니 XM4·XM5·XM6 3세대 비교 [[소니 3세대 비교 글감]]\"), None, \"\", True)\n\n안됨 = \"게스트판에서는 쓸 수 없는 기능이에요\"\n\n\ndef _상태():\n    st = V.목록()\n    st[\"claude\"] = []\n    st[\"me\"] = {\"id\": \"guest\", \"name\": \"게스트\", \"owner\": False, \"locked\": False}\n    st[\"icloud\"] = {\"connected\": False}\n    st[\"ai\"] = {\"ready\": False}\n    st[\"now\"] = time.time()\n    return st\n\n\ndef _get(name, q):\n    if name == \"rev\":\n        return {\"rev\": V.rev}\n    if name == \"state\":\n        return _상태()\n    if name == \"note\":\n        return V.읽기(q.get(\"path\", \"\"))\n    if name == \"search\":\n        return {\"results\": V.검색(q.get(\"q\", \"\"), int(q.get(\"limit\") or 200), q.get(\"archived\") == \"1\")}\n    if name == \"backlinks\":\n        return V.백링크(q.get(\"path\", \"\"))\n    if name == \"graph\":\n        return V.그래프()\n    if name == \"history\":\n        return {\"items\": V.기록목록(q.get(\"path\", \"\"))}\n    if name == \"history/get\":\n        return {\"text\": V.기록읽기(q.get(\"path\", \"\"), q.get(\"id\", \"\"))}\n    if name == \"trash\":\n        return {\"items\": V.휴지통목록()}\n    if name == \"trash/get\":\n        return {\"text\": V.휴지통읽기(q.get(\"id\", \"\"))}\n    if name == \"templates\":\n        return {\"items\": V.템플릿목록()}\n    if name == \"icloud/status\":\n        return {\"connected\": False}\n    if name == \"ai/status\":\n        return {\"ready\": False}\n    if name in (\"backups\", \"sessions\"):\n        return {\"items\": []}\n    if name == \"calendar/events\":\n        return {\"events\": []}\n    raise NotImplementedError(name)\n\n\ndef _post(name, d, dev):\n    if name == \"note/save\":\n        n = V.저장(d[\"path\"], d.get(\"text\", \"\"), d.get(\"base\"), dev, bool(d.get(\"force\")))\n        return {\"ver\": n[\"ver\"], \"meta\": n, \"rev\": V.rev}\n    if name == \"note/create\":\n        text = d.get(\"text\", \"\")\n        if d.get(\"template\"):\n            text = V.템플릿적용(d[\"template\"], d.get(\"title\", \"\"))\n        folder = d.get(\"folder\")\n        if folder is None:\n            folder = V.settings.get(\"새노트폴더\", \"\")\n        return {\"path\": V.만들기(folder, d.get(\"title\") or \"제목 없음\", text, dev), \"rev\": V.rev}\n    if name == \"note/rename\":\n        new = d.get(\"newPath\")\n        if not new:\n            folder = d[\"path\"].rpartition(\"/\")[0]\n            new = (folder + \"/\" if folder else \"\") + 파일이름(d[\"title\"]) + \".md\"\n        rel, n = V.옮기기(d[\"path\"], new, d.get(\"updateLinks\", True), dev)\n        return {\"path\": rel, \"linksUpdated\": n, \"rev\": V.rev}\n    if name == \"note/move\":\n        p = d[\"path\"]\n        folder = (d.get(\"folder\") or \"\").strip(\"/\")\n        rel, n = V.옮기기(p, (folder + \"/\" if folder else \"\") + p.rsplit(\"/\", 1)[-1], True, dev)\n        return {\"path\": rel, \"rev\": V.rev}\n    표시 = {\"note/pin\": \"고정\", \"note/readonly\": \"읽기전용\", \"note/archive\": \"보관\"}\n    if name in 표시:\n        V.표시(d[\"path\"], 표시[name], bool(d.get(\"on\")))\n        return {\"rev\": V.rev}\n    if name == \"note/trash\":\n        return {\"id\": V.버리기(d[\"path\"], dev), \"rev\": V.rev}\n    if name == \"trash/restore\":\n        return {\"path\": V.되살리기(d[\"id\"]), \"rev\": V.rev}\n    if name == \"trash/purge\":\n        return {\"count\": V.영구삭제(d.get(\"id\")), \"rev\": V.rev}\n    if name == \"history/restore\":\n        text = V.기록읽기(d[\"path\"], d[\"id\"])\n        n = V.저장(d[\"path\"], text, None, dev, True)\n        return {\"ver\": n[\"ver\"], \"text\": text, \"rev\": V.rev}\n    if name == \"folder/create\":\n        return {\"path\": V.폴더만들기(d[\"path\"]), \"rev\": V.rev}\n    if name == \"folder/rename\":\n        return {\"path\": V.폴더옮기기(d[\"path\"], d[\"newPath\"]), \"rev\": V.rev}\n    if name == \"folder/delete\":\n        V.폴더지우기(d[\"path\"])\n        return {\"rev\": V.rev}\n    if name == \"tag/rename\":\n        return {\"count\": V.태그바꾸기(d[\"old\"], d[\"new\"], dev), \"rev\": V.rev}\n    if name == \"daily\":\n        날짜 = datetime.fromisoformat(d.get(\"date\") or datetime.now().strftime(\"%Y-%m-%d\"))\n        rel, made = V.일기(날짜, d.get(\"create\", True), dev, d.get(\"journal\"))\n        return {\"path\": rel, \"created\": made, \"exists\": rel in V.notes, \"rev\": V.rev}\n    if name == \"template/apply\":\n        return {\"text\": V.템플릿적용(d[\"path\"], d.get(\"title\", \"\"))}\n    if name == \"order\":\n        return {\"order\": V.순서바꾸기(d), \"rev\": V.rev}\n    if name == \"settings\":\n        if \"일기종류\" in d:\n            V.일기종류바꾸기(d.pop(\"일기종류\"))\n        return {\"settings\": V.설정바꾸기(d), \"journals\": V.journals, \"rev\": V.rev}\n    raise NotImplementedError(name)\n\n\ndef handle(method, name, q, body, dev):\n    try:\n        if method == \"GET\":\n            data = _get(name, json.loads(q or \"{}\"))\n        else:\n            data = _post(name, json.loads(body) if body else {}, dev or \"guest\")\n        return json.dumps({\"status\": 200, \"data\": data}, ensure_ascii=False)\n    except 충돌 as e:\n        return json.dumps({\"status\": 409, \"data\": {\"conflict\": True, \"text\": e.text, \"ver\": e.ver}}, ensure_ascii=False)\n    except 없음 as e:\n        return json.dumps({\"status\": 404, \"data\": {\"error\": \"노트가 없습니다: %s\" % e}}, ensure_ascii=False)\n    except NotImplementedError:\n        return json.dumps({\"status\": 400, \"data\": {\"error\": 안됨}}, ensure_ascii=False)\n    except (ValueError, KeyError) as e:\n        return json.dumps({\"status\": 400, \"data\": {\"error\": str(e)}}, ensure_ascii=False)\n    except Exception as e:\n        return json.dumps({\"status\": 500, \"data\": {\"error\": \"오류: %s\" % e}}, ensure_ascii=False)\n"};
